    "d /run/php 0755 root root -"
    "d /var/log/apache2 0755 root root -"
    "d /var/log/web 0750 root adm -"
    "f /var/log/web/amber-access.log 0640 root adm -"
    "f /var/log/web/amber-error.log 0640 root adm -"
    "f /var/log/web/cobalt-access.log 0640 root adm -"
    "f /var/log/web/cobalt-error.log 0640 root adm -"
    "d /srv/node 0755 root root -"
    "d /var/www/html 0755 root root -"
  ];

  system.activationScripts.nodeSeed = {
    deps = [ "users" "groups" ];
    text = ''
      if [ ! -e /srv/node/index.html ]; then
        printf '%s\n' 'node service' > /srv/node/index.html
        chmod 644 /srv/node/index.html
      fi
      if [ ! -e /var/www/html/index.html ]; then
        printf '%s\n' '<html><body><h1>It works!</h1></body></html>' > /var/www/html/index.html
      fi
      ${lib.concatStringsSep "\n" (lib.mapAttrsToList seedTenant tenants)}
    '';
  };

  services.openssh = {
    enable = true;
    settings = {
      PasswordAuthentication = false;
      KbdInteractiveAuthentication = false;
      PermitRootLogin = "prohibit-password";
    };
  };

  security.sudo.extraRules = [
    {
      users = [ "amber" ];
      runAs = ":adm";
      commands = [
        { command = "${pkgs.coreutils}/bin/cat /var/log/web/amber-access.log"; options = [ "NOPASSWD" ]; }
        { command = "${pkgs.coreutils}/bin/cat /var/log/web/amber-error.log"; options = [ "NOPASSWD" ]; }
      ];
    }
    {
      users = [ "cobalt" ];
      runAs = ":adm";
      commands = [
        { command = "${pkgs.coreutils}/bin/cat /var/log/web/cobalt-access.log"; options = [ "NOPASSWD" ]; }
        { command = "${pkgs.coreutils}/bin/cat /var/log/web/cobalt-error.log"; options = [ "NOPASSWD" ]; }
      ];
    }
  ];

  services.httpd = {
    enable = true;
    package = httpd;
    user = "www-data";
    group = "www-data";
    configFile = httpdConf;
  };

  services.phpfpm = {
    phpPackage = php;
    phpOptions = ''
      expose_php = Off
      error_reporting = E_ALL & ~E_DEPRECATED & ~E_STRICT
      display_errors = Off
      log_errors = On
      session.save_handler = files
      session.gc_maxlifetime = 1440
    '';
    settings.error_log = "/var/log/php-fpm.log";
    pools = {
      amber = phpPool "amber";
      cobalt = phpPool "cobalt";
    };
  };

  services.mysql = {
    enable = true;
    package = pkgs.mariadb;
    initialScript = mysqlInit;
  };

  services.postgresql = {
    enable = true;
    package = pkgs.postgresql_17;
    extensions = ps: [ ps.postgis ];
    authentication = lib.mkOverride 10 ''
      local all all peer
      host all all 127.0.0.1/32 scram-sha-256
      host all all ::1/128 scram-sha-256
    '';
    initialScript = pgInit;
  };

  services.memcached = {
    enable = true;
    listen = "127.0.0.1";
    port = 11211;
    maxMemory = 32;
    user = "memcache";
    extraOptions = [ "-U" "0" ];
  };

  environment.systemPackages = [
    httpd
    php
    python
    pkgs.mariadb
    pkgs.postgresql_17
    pkgs.memcached
    pkgs.curl
    pkgs.wget
    pkgs.jq
    pkgs.git
    pkgs.rsync
    pkgs.vim
    pkgs.nano
    pkgs.htop
    pkgs.tmux
    pkgs.screen
    pkgs.strace
    pkgs.tcpdump
    pkgs.lsof
    pkgs.socat
    pkgs.netcat-openbsd
    pkgs.bc
    pkgs.file
    pkgs.acl
    pkgs.mtr
    pkgs.iputils
    pkgs.bind.dnsutils
    pkgs.openssl
  ];
}
