  };

  phpPool = name: {
    user = name;
    group = name;
    phpPackage = php;
    settings = {
      "listen" = "/run/php/php-${name}-fpm.sock";
      "listen.owner" = "www-data";
      "listen.group" = "www-data";
      "listen.mode" = "0660";
      "pm" = "dynamic";
