arguments.command:
cd /app/submission && python3 - <<'EOF'
p='/app/submission/replica.nix'
s=open(p).read()
old='''    <Directory /home/${name}/public_html/cgi-bin>
        SetHandler cgi-script
'''
new='''    <Directory /home/${name}/public_html/cgi-bin>
        SetHandler "proxy:unix:/run/fcgiwrap-${name}.sock|fcgi://localhost"
'''
assert s.count(old)==1
s=s.replace(old,new)
old2='''  services.phpfpm = {'''
new2='''  services.fcgiwrap.instances = lib.mapAttrs (name: t: {
    process.user = name;
    process.group = name;
    socket = {
      type = "unix";
      address = "/run/fcgiwrap-${name}.sock";
      user = "www-data";
      group = "www-data";
      mode = "0660";
    };
  }) tenants;

  services.phpfpm = {'''
assert s.count(old2)==1
s=s.replace(old2,new2)
open(p,'w').write(s)
print("ok")
EOF
pkill -f "build-replica" ; pkill -f "nix build" ; sleep 3; cd /tmp && timeout 900 /opt/contract/check-replica 2>&1 | tail -2 && (nohup /opt/contract/build-replica > /tmp/build.log 2>&1; echo "BUILD_EXIT=$?" >> /tmp/build.log) >/dev/null 2>&1 & sleep 5; tail -2 /tmp/build.log

